 16	POST {{baseUrl}}/api/checkout
 17	Content-Type: application/json
 18	
 19	{
 20	  "usr": "João",
 21	  "eml": "joao@teste.com",
 22	  "pwd": "123",
 23	  "c_id": 1,
 24	  "card": "5111222233334444"
 25	}
