 13	    console.log(`[LOG] Salvando no cache: ${key}`);
 14	    globalCache[key] = data;
 15	}
 16	
 17	function badCrypto(pwd) {
 18	    let hash = "";
 19	    for(let i = 0; i < 10000; i++) {
 20	        hash += Buffer.from(pwd).toString('base64').substring(0, 2);
 21	    }
 22	    return hash.substring(0, 10);
 23	}
