  2	const { config, logAndCache, badCrypto, totalRevenue } = require('./utils');
  3	
  4	class AppManager {
  5	    constructor() {
  6	
  7	        this.db = new sqlite3.Database(':memory:');
  8	    }
  9	
 10	    initDb() {
 11	        this.db.serialize(() => {
 12	            this.db.run("CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT, email TEXT, pass TEXT)");
 13	            this.db.run("CREATE TABLE courses (id INTEGER PRIMARY KEY, title TEXT, price REAL, active INTEGER)");
 14	            this.db.run("CREATE TABLE enrollments (id INTEGER PRIMARY KEY, user_id INTEGER, course_id INTEGER)");
 15	            this.db.run("CREATE TABLE payments (id INTEGER PRIMARY KEY, enrollment_id INTEGER, amount REAL, status TEXT)");
 16	            this.db.run("CREATE TABLE audit_logs (id INTEGER PRIMARY KEY, action TEXT, created_at DATETIME)");
 17	            
 18	            this.db.run("INSERT INTO users (name, email, pass) VALUES ('Leonan', 'leonan@fullcycle.com.br', '123')");
 19	            this.db.run("INSERT INTO courses (title, price, active) VALUES ('Clean Architecture', 997.00, 1), ('Docker', 497.00, 1)");
 20	            this.db.run("INSERT INTO enrollments (user_id, course_id) VALUES (1, 1)");
 21	            this.db.run("INSERT INTO payments (enrollment_id, amount, status) VALUES (1, 997.00, 'PAID')");
 22	        });
 23	    }
 24	
 25	    setupRoutes(app) {
 26	        const self = this;
 27	
 28	        app.post('/api/checkout', (req, res) => {
 29	            let u = req.body.usr;
 30	            let e = req.body.eml;
 31	            let p = req.body.pwd;
 32	            let cid = req.body.c_id;
 33	            let cc = req.body.card;
 34	
 35	            if (!u || !e || !cid || !cc) return res.status(400).send("Bad Request");
 36	
 37	            this.db.get("SELECT * FROM courses WHERE id = ? AND active = 1", [cid], (err, course) => {
 38	                if (err || !course) return res.status(404).send("Curso não encontrado");
 39	
 40	                this.db.get("SELECT id FROM users WHERE email = ?", [e], (err, user) => {
 41	                    if (err) return res.status(500).send("Erro DB");
 42	
 43	                    let processPaymentAndEnroll = (userId) => {
 44	
 45	                        console.log(`Processando cartão ${cc} na chave ${config.paymentGatewayKey}`);
 46	                        let status = cc.startsWith("4") ? "PAID" : "DENIED";
 47	
 48	                        if (status === "DENIED") return res.status(400).send("Pagamento recusado");
 49	
 50	                        this.db.run("INSERT INTO enrollments (user_id, course_id) VALUES (?, ?)", [userId, cid], function(err) {
 51	                            if (err) return res.status(500).send("Erro Matrícula");
 52	                            let enrId = this.lastID;
 53	
 54	                            self.db.run("INSERT INTO payments (enrollment_id, amount, status) VALUES (?, ?, ?)", [enrId, course.price, status], function(err) {
 55	                                if (err) return res.status(500).send("Erro Pagamento");
 56	
 57	                                self.db.run("INSERT INTO audit_logs (action, created_at) VALUES (?, datetime('now'))", [`Checkout curso ${cid} por ${userId}`], (err) => {
 58	                                    
 59	                                    logAndCache(`last_checkout_${userId}`, course.title);
 60	                                    res.status(200).json({ msg: "Sucesso", enrollment_id: enrId });
 61	                                });
 62	                            });
 63	                        });
 64	                    };
 65	
 66	                    if (!user) {
 67	
 68	                        let hash = badCrypto(p || "123456");
 69	                        this.db.run("INSERT INTO users (name, email, pass) VALUES (?, ?, ?)", [u, e, hash], function(err) {
 70	                            if (err) return res.status(500).send("Erro ao criar usuário");
 71	                            processPaymentAndEnroll(this.lastID);
 72	                        });
 73	                    } else {
 74	                        processPaymentAndEnroll(user.id);
 75	                    }
 76	                });
 77	            });
 78	        });
 79	
 80	        app.get('/api/admin/financial-report', (req, res) => {
 81	            let report = [];
 82	
 83	            this.db.all("SELECT * FROM courses", [], (err, courses) => {
 84	                if (err) return res.status(500).send("Erro DB");
 85	                
 86	                let coursesPending = courses.length;
 87	                if (coursesPending === 0) return res.json(report);
 88	
 89	                courses.forEach(c => {
 90	                    let courseData = { course: c.title, revenue: 0, students: [] };
 91	                    
 92	                    this.db.all("SELECT * FROM enrollments WHERE course_id = ?", [c.id], (err, enrollments) => {
 93	                        let enrPending = enrollments.length;
 94	                        
 95	                        if (enrPending === 0) {
 96	                            report.push(courseData);
 97	                            coursesPending--;
 98	                            if (coursesPending === 0) res.json(report);
 99	                            return;
100	                        }
101	
102	                        enrollments.forEach(enr => {
103	
104	                            this.db.get("SELECT name, email FROM users WHERE id = ?", [enr.user_id], (err, user) => {
105	                                
106	                                this.db.get("SELECT amount, status FROM payments WHERE enrollment_id = ?", [enr.id], (err, payment) => {
107	                                    
108	                                    if (payment && payment.status === 'PAID') {
109	                                        courseData.revenue += payment.amount;
110	                                    }
111	                                    
112	                                    courseData.students.push({
113	                                        student: user ? user.name : 'Unknown',
114	                                        paid: payment ? payment.amount : 0
115	                                    });
116	
117	                                    enrPending--;
118	                                    if (enrPending === 0) {
119	                                        report.push(courseData);
120	                                        coursesPending--;
121	                                        if (coursesPending === 0) res.json(report);
122	                                    }
123	                                });
124	                            });
125	                        });
126	                    });
127	                });
128	            });
129	        });
130	
131	        app.delete('/api/users/:id', (req, res) => {
132	            let id = req.params.id;
133	            this.db.run("DELETE FROM users WHERE id = ?", [id], (err) => {
134	
135	                res.send("Usuário deletado, mas as matrículas e pagamentos ficaram sujos no banco.");
136	            });
137	        });
138	    }
139	}
140	
141	module.exports = AppManager;

